use kni_core::source_provenance::*;
use kni_core::reference_slice::{Point,Span,ReferenceRing};
fn p(x:f64,y:f64)->Point{Point{x,y}}
fn parent()->PreEmissionSpan{PreEmissionSpan{parent_index:0,start:p(0.1,0.1),span:Span::Line{end:p(2.1,0.1)},source:Some(SourceInterval{arc:3,first_sample:0,last_sample:1,samples:vec![p(0.1,0.1),p(2.1,0.1)]})}}
#[test]fn exact_round_binding_retains_interval(){let r=ReferenceRing{start:p(0.,0.),spans:vec![Span::Line{end:p(2.,0.)}]};let x=bind_emission(2,vec![parent()],&r);assert!(matches!(x.emitted[0].binding,ParentBinding::ExactRoundedParent{parent_index:0,..}));assert!(x.unmatched_parent_indices.is_empty());}
#[test]fn geometry_change_unresolved_not_nearest_match(){let r=ReferenceRing{start:p(0.,0.),spans:vec![Span::Line{end:p(3.,0.)}]};let x=bind_emission(0,vec![parent()],&r);assert!(matches!(x.emitted[0].binding,ParentBinding::Unresolved{reason:UnresolvedReason::GeometryChangedAfterFit}));assert_eq!(x.unmatched_parent_indices,vec![0]);}
#[test]fn ambiguous_parent_unresolved(){let mut b=parent();b.parent_index=1;let r=ReferenceRing{start:p(0.,0.),spans:vec![Span::Line{end:p(2.,0.)}]};assert!(matches!(bind_emission(0,vec![parent(),b],&r).emitted[0].binding,ParentBinding::Unresolved{reason:UnresolvedReason::AmbiguousParent}));}
#[test]fn synthetic_closure_explicit(){let mut q=parent();q.source=None;let r=ReferenceRing{start:p(0.,0.),spans:vec![Span::Line{end:p(2.,0.)}]};assert!(matches!(bind_emission(0,vec![q],&r).emitted[0].binding,ParentBinding::SyntheticClosure{..}));}
#[test]fn invalid_interval_not_claimed(){let mut q=parent();q.source.as_mut().unwrap().last_sample=5;let r=ReferenceRing{start:p(0.,0.),spans:vec![Span::Line{end:p(2.,0.)}]};assert!(matches!(bind_emission(0,vec![q],&r).emitted[0].binding,ParentBinding::Unresolved{reason:UnresolvedReason::InvalidSourceInterval}));}

#[test]fn fitted_arc_is_not_raw_interval_and_region_abstains(){let r=ReferenceRing{start:p(0.,0.),spans:vec![Span::Line{end:p(2.,0.)}]};let x=bind_emission(0,vec![parent()],&r);assert_eq!(x.emitted[0].status,BindingStatus::UnresolvedRawInterval);assert_eq!(x.emitted[0].role,SpanRole::Unknown);assert!(!region_ready(&x));}
#[test]fn raw_interval_wrap_reversal_and_corruption_fail_closed(){let mut l=kni_core::capture::CaptureLineage{captured_ring_index:2,raw_point_count:10,reversed:false,raw_start_index:0,retained_raw_indices:vec![1,4,8],corner_events:vec![],detector_policy_receipt:"test".into()};let x=recorded_raw_interval(&l,2,0).unwrap();assert!(x.wraps);assert_eq!(x.captured_ring_index,2);l.retained_raw_indices[2]=10;assert!(recorded_raw_interval(&l,2,0).is_none());l.retained_raw_indices=vec![8,4,1];l.reversed=true;l.raw_start_index=9;assert!(recorded_raw_interval(&l,2,0).unwrap().wraps);assert!(recorded_raw_interval(&l,0,0).is_none());let mut x=recorded_raw_interval(&l,0,2).unwrap();x.wraps=true;assert!(!x.valid());}
